parameters.jsCode:
const createRes = $('Create eLabFTW Experiment').item.json;
const expId = createRes.id || (createRes.body && createRes.body.id) || (createRes.headers && createRes.headers.location ? createRes.headers.location.split('/').pop() : null);
const elabBase = 'https://elab.uni-muenster.de';

const expUrl = expId ? `${elabBase}/experiments.php?mode=view&id=${expId}` : null;

return {
  json: {
    status: 'success',
    server_time: new Date().toISOString(),
    message: expId 
      ? `✓ Experiment #${expId} in eLabFTW angelegt (inkl. Extra Fields)!` 
      : '✓ Metadaten erfolgreich empfangen!',
    elabftw_id: expId,
    elabftw_url: expUrl
  }
};

return {
  json: {
    status: 'success',
    server_time: new Date().toISOString(),
    message: '✓ Metadaten erfolgreich empfangen (keine Integration aktiv).'
  }
};
